import {
  Group,
  Mesh,
  TorusKnotGeometry,
  CylinderGeometry,
  TorusGeometry,
  PlaneGeometry,
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
  PointLight,
  DirectionalLight,
  DoubleSide,
} from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  float,
  mix,
  smoothstep,
  oneMinus,
  clamp,
  length,
  time,
  texture,
  normalView,
  mx_noise_float,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config?.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [
      { at: 0, hex: '#0b0b10' },
      { at: 0.7, hex: '#101017' },
      { at: 1, hex: '#16161d' },
    ],
  };

  const root = new Group();
  root.userData.handlers = {};

  const disposables = [];
  const timelines = [];
  const primitiveHandles = [];

  // ---------------------------------------------------------------
  // BACKDROP — 7x6 vertical gradient plane
  // ---------------------------------------------------------------
  const stops = colors.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.7, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];
  const c0 = new THREE.Color(stops[0].hex);
  const c1 = new THREE.Color(stops[1].hex);
  const c2 = new THREE.Color(stops[2].hex);

  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  const yN = uv().y;
  const stageA = mix(vec3(c0.r, c0.g, c0.b), vec3(c1.r, c1.g, c1.b), smoothstep(0.0, 0.7, yN));
  const stageFinal = mix(stageA, vec3(c2.r, c2.g, c2.b), smoothstep(0.7, 1.0, yN));
  backdropMat.colorNode = stageFinal;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -3);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------------------------------------------------------------
  // CONTACT SHADOW — radial falloff plane
  // ---------------------------------------------------------------
  const shadowGeo = new PlaneGeometry(3, 3);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    color: 0x000000,
  });
  const distNode = length(uv().sub(vec2(0.5, 0.5))).mul(3.0);
  const shadowAlpha = float(0.6).mul(oneMinus(clamp(smoothstep(1.1, 1.5, distNode), 0.0, 1.0)));
  shadowMat.opacityNode = shadowAlpha;
  const shadowPlane = new Mesh(shadowGeo, shadowMat);
  shadowPlane.rotation.x = -Math.PI / 2;
  shadowPlane.position.set(0, -0.36, 0);
  root.add(shadowPlane);
  disposables.push(shadowGeo, shadowMat);

  // ---------------------------------------------------------------
  // PEDESTAL — cylinder + chamfer ring
  // ---------------------------------------------------------------
  const pedestalGeo = new CylinderGeometry(1.1, 1.1, 0.5, 48);
  const pedestalMat = new MeshPhysicalNodeMaterial({
    color: new THREE.Color(colors.surface ?? '#14141a'),
    roughness: 0.7,
    metalness: 0.35,
    clearcoat: 0.1,
    envMapIntensity: 0.7,
  });
  const pedestal = new Mesh(pedestalGeo, pedestalMat);
  pedestal.position.set(0, -0.6, 0);
  root.add(pedestal);
  disposables.push(pedestalGeo, pedestalMat);

  const chamferGeo = new TorusGeometry(1.1, 0.03, 10, 64);
  const chamferMat = new MeshPhysicalNodeMaterial({
    color: new THREE.Color(colors.surface ?? '#14141a').offsetHSL(0, 0, 0.08),
    roughness: 0.55,
    metalness: 0.4,
    envMapIntensity: 0.7,
  });
  const chamfer = new Mesh(chamferGeo, chamferMat);
  chamfer.rotation.x = Math.PI / 2;
  chamfer.position.set(0, -0.35, 0);
  root.add(chamfer);
  disposables.push(chamferGeo, chamferMat);

  // ---------------------------------------------------------------
  // TORUS KNOT — brushed-metal PBR material study
  // ---------------------------------------------------------------
  const knotGroup = new Group();
  knotGroup.position.set(0, 0.4, 0);
  root.add(knotGroup);

  const knotGeo = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knotMat = new MeshPhysicalNodeMaterial({
    color: new THREE.Color(colors.ink ?? '#16161d').lerp(new THREE.Color('#c9cdd4'), 0.55),
    roughness: 0.55,
    metalness: 0.55,
    clearcoat: 0.22,
    clearcoatRoughness: 0.35,
    envMapIntensity: 0.7,
  });
  knotMat.anisotropy = 0.9;
  knotMat.anisotropyRotation = Math.PI / 2;

  // imperfection pass: procedural scratch-noise normal perturbation
  const scratchA = mx_noise_float(vec3(uv().mul(300.0), 0.0));
  const scratchB = mx_noise_float(vec3(uv().mul(300.0).add(vec2(13.7, 7.1)), 0.0));
  const normalPerturb = vec3(scratchA, scratchB, 0.0).mul(0.15);
  knotMat.normalNode = normalView.add(normalPerturb).normalize();

  // roughness jitter (2% value jitter) — fallback until texture arrives
  const roughJitter = mx_noise_float(vec3(uv().mul(180.0), time.mul(0.05))).mul(0.02);
  knotMat.roughnessNode = clamp(float(0.55).add(roughJitter), 0.05, 1.0);

  const knot = new Mesh(knotGeo, knotMat);
  knotGroup.add(knot);
  disposables.push(knotGeo, knotMat);

  let roughnessTexHandle = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.wrapS = THREE.RepeatWrapping;
      tex.wrapT = THREE.RepeatWrapping;
      roughnessTexHandle = tex;
      const mapFactor = texture(tex).r.mul(1.0 / 0.9);
      knotMat.roughnessNode = clamp(
        float(0.55).mul(mapFactor).add(roughJitter),
        0.05,
        1.0
      );
      knotMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---------------------------------------------------------------
  // LIGHTS — node-local rim + fill (scene supplies ambient + key)
  // ---------------------------------------------------------------
  const rimLight = new DirectionalLight(new THREE.Color(colors.accent ?? '#ff2a38'), 0.6);
  rimLight.position.set(-3, 1.6, -2.2);
  root.add(rimLight);

  const fillLight = new PointLight(0xffffff, 0.55, 8, 2);
  fillLight.position.set(2.2, 1.2, 2.4);
  root.add(fillLight);

  // ---------------------------------------------------------------
  // TEXT — headline + caption on 0.25-unit rhythm baselines
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [
    { text: 'Material study 03', role: 'headline', typography: { fontSize: 68 } },
    { text: 'GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT', role: 'caption', typography: { fontSize: 18 } },
  ];

  for (const item of items) {
    const role = item.role ?? 'body';
    const fontSize = item.typography?.fontSize ?? (role === 'headline' ? 68 : 18);
    const isHeadline = role === 'headline';
    const textNode = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize,
      color: colors.paper ?? '#e8ecf2',
      align: 'center',
      letterSpacingPx: isHeadline ? fontSize * -0.005 : fontSize * 0.08,
    });
    textNode.position.set(0, isHeadline ? -1.2 : -1.6, 0.3);
    root.add(textNode);
  }

  // ---------------------------------------------------------------
  // MOTION — weighted-settle entrance + idle breathing
  // ---------------------------------------------------------------
  root.scale.setScalar(0.96);
  root.position.y = 0.15;
  const settleTl = gsap.timeline();
  settleTl.to(root.scale, {
    x: 1.0, y: 1.0, z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  }, 0);
  settleTl.to(root.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);
  timelines.push(settleTl);

  const breatheTl = gsap.timeline({ repeat: -1, yoyo: true });
  breatheTl.to(knotGroup.scale, {
    x: 1.02, y: 1.02, z: 1.02,
    duration: 4.0,
    ease: 'sine.inOut',
  });
  timelines.push(breatheTl);

  // ---------------------------------------------------------------
  // CINEMATIC PRIMITIVES
  // ---------------------------------------------------------------
  const primitiveConfigs = config.cinematicPrimitives ?? [
    { name: 'orbit', trigger: 'load', params: { speed: 0.1, radius: 0.4 } },
  ];
  for (const prim of primitiveConfigs) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(knotGroup, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---------------------------------------------------------------
  // CLEANUP
  // ---------------------------------------------------------------
  root.userData.cleanup = () => {
    for (const tl of timelines) {
      tl.kill();
    }
    for (const handle of primitiveHandles) {
      handle?.timeline?.kill?.();
      handle?.cleanup?.();
    }
    for (const d of disposables) {
      d?.dispose?.();
    }
    if (roughnessTexHandle) {
      roughnessTexHandle.dispose?.();
    }
    root.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose?.();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose?.());
        } else {
          obj.material.dispose?.();
        }
      }
    });
  };

  return root;
}
